function u(t){return t.toLowerCase().replace(/ł/g,"l").normalize("NFD").replace(/[\u0300-\u036f]/g,"")}function m(t,e){let n=u(t);return u(e).split(/\s+/).filter(Boolean).every(r=>{if(n.includes(r))return!0;if(r.length>=5){let o=r.slice(0,Math.max(4,r.length-2));return n.includes(o)}return!1})}function p(t,e){return Math.abs(e-1)<.001?t:t.replace(/(^|\s)(\d+(?:[.,]\d+)?)(?=\s?(?:g|kg|ml|l|szt|łyż|szkl|krom|plastr|ząb|szczypt|\b))/gi,(n,s,r)=>{let o=parseFloat(r.replace(",","."));if(Number.isNaN(o))return`${s}${r}`;let a=Math.round(o*e*10)/10,c=Number.isInteger(a)?String(a):String(a).replace(".",",");return`${s}${c}`})}function g(t){let e=Math.abs(t)%100;if(e>=11&&e<=19)return"porcji";let n=Math.abs(t)%10;return n===1?"porcja":n>=2&&n<=4?"porcje":"porcji"}function b(t,e,n){let s=Math.max(0,t)*4,r=Math.max(0,e)*4,o=Math.max(0,n)*9,a=s+r+o;if(a<=0)return{protein:33,carbs:34,fat:33};let c=Math.round(s/a*100),i=Math.round(r/a*100),l=Math.max(0,100-c-i);return{protein:c,carbs:i,fat:l}}export{m as a,p as b,g as c,b as d};
